    {
      "name": "Finset.exists_le_card_fiber_of_mul_le_card_of_maps_to",
      "module_name": "Mathlib.Combinatorics.Pigeonhole",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} [inst : DecidableEq β] {s : Finset α} {t : Finset β} {f : α → β} {n : ℕ},\n  (∀ a ∈ s, f a ∈ t) → t.Nonempty → t.card * n ≤ s.card → ∃ y ∈ t, n ≤ {x ∈ s | f x = y}.card"
    },
    {
      "name": "Set.exists_ne_map_eq_of_ncard_lt_of_maps_to",
      "module_name": "Mathlib.Data.Set.Card",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} {s : Set α} {t : Set β},\n  t.ncard < s.ncard →\n    ∀ {f : α → β},\n      (∀ a ∈ s, f a ∈ t) →\n        autoParam t.Finite Set.exists_ne_map_eq_of_ncard_lt_of_maps_to._auto_1 → ∃ x ∈ s, ∃ y ∈ s, x ≠ y ∧ f x = f y"
    },
    {
      "name": "Finset.exists_lt_card_fiber_of_mul_lt_card_of_maps_to",
      "module_name": "Mathlib.Combinatorics.Pigeonhole",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} [inst : DecidableEq β] {s : Finset α} {t : Finset β} {f : α → β} {n : ℕ},\n  (∀ a ∈ s, f a ∈ t) → t.card * n < s.card → ∃ y ∈ t, n < {x ∈ s | f x = y}.card"
    },
    {
      "name": "Fintype.exists_lt_card_fiber_of_mul_lt_card",
      "module_name": "Mathlib.Combinatorics.Pigeonhole",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} [inst : DecidableEq β] [inst_1 : Fintype α] [inst_2 : Fintype β] (f : α → β) {n : ℕ},\n  Fintype.card β * n < Fintype.card α → ∃ y, n < {x | f x = y}.card"
    },
    {
      "name": "Fintype.exists_ne_map_eq_of_card_lt",
      "module_name": "Mathlib.Data.Fintype.Pigeonhole",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : Fintype α] [inst_1 : Fintype β] (f : α → β),\n  Fintype.card β < Fintype.card α → ∃ x y, x ≠ y ∧ f x = f y"
    },
    {
      "name": "Fintype.exists_card_fiber_le_of_card_le_mul",
      "module_name": "Mathlib.Combinatorics.Pigeonhole",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} [inst : DecidableEq β] [inst_1 : Fintype α] [inst_2 : Fintype β] (f : α → β) {n : ℕ}\n  [Nonempty β], Fintype.card α ≤ Fintype.card β * n → ∃ y, {x | f x = y}.card ≤ n"
    }
  ]
}
